"""Contact sheet rows for substitute teachers."""

from typing import List, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError

Cells = Tuple[str, ...]

def _contact_cells(student: Student) -> Cells:
    name = student.display_name
    if not student.email:
        raise ProjectError(f"No email: {name}")
    return (name, student.section, student.email)

def _join(cells: Cells, sizes: List[int]) -> str:
    pairs = zip(cells, sizes)
    padded = [text.ljust(size) for text, size in pairs]
    return "  ".join(padded).rstrip()

def _align(table: List[Cells]) -> List[str]:
    sizes = [max(map(len, field)) for field in zip(*table)]
    return [_join(cells, sizes) for cells in table]

def _sort_key(student: Student) -> str:
    return student.display_name

# ---
def format_contacts(students: List[Student]) -> List[str]:
    """Aligned name, section, email rows, sorted by name."""
    if not students:
        raise ProjectError("No students to list")
    ordered = sorted(students, key=_sort_key)
    table = [_contact_cells(pupil) for pupil in ordered]
    return _align(table)
